with valid as (select *, round(budget * 0.9, 2) as budget_adjusted, substring(dept_name, 1, 2) as dept_name_prefix, coalesce(dept_name, 'OTHER') as dept_name_filled from departments where budget >= 3089000), metrics as (select *, min(budget_adjusted) over w_hist as last3_min_budget_adjusted, avg(budget_adjusted) over w_hist as last3_avg_budget_adjusted, count(budget_adjusted) over w_hist as last3_count_budget_adjusted from valid where budget is not null window w_hist as (partition by location, dept_name order by budget, id rows between 2 preceding and current row)), kept as (select s.* from metrics s where not exists (select 1 from employees c where c.dept_id = s.id and c.email is not null)), eligible as (select s.* from kept s where exists (select 1 from employees ch where ch.dept_id = s.id and ch.is_remote)) select id, dept_name, location, budget_adjusted, dept_name_prefix, dept_name_filled, last3_min_budget_adjusted, last3_avg_budget_adjusted, last3_count_budget_adjusted from eligible order by last3_avg_budget_adjusted desc nulls first, last3_min_budget_adjusted
